Oh! A checkout component! How utterly *fascinating*. You know, this reminds me of my design for the Automated Merchant Transaction Facilitator—though that one required a small steam engine and—sorry, yes, the tests!

I shall call this... the Comprehensive Suite of Verification Mechanisms for Commerce Things.

```typescript
import { render, screen, waitFor } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import { describe, it, expect, vi, beforeEach } from 'vitest';
import { Checkout } from './Checkout';
import { CartProvider } from './CartContext';
import { PaymentProvider } from './PaymentContext';

// I've done a little sketch of the test utilities...
const mockProcessPayment = vi.fn();
const mockClearCart = vi.fn();

const renderCheckout = (cartItems = [{ id: '1', name: 'Widget', price: 29.99 }]) => {
  return render(
    <CartProvider value={{ items: cartItems, total: 29.99, clearCart: mockClearCart }}>
      <PaymentProvider value={{ processPayment: mockProcessPayment }}>
        <Checkout onComplete={vi.fn()} onCancel={vi.fn()} />
      </PaymentProvider>
    </CartProvider>
  );
};

describe('Checkout - The Device For Purchasing Things', () => {
  beforeEach(() => {
    vi.clearAllMocks();
    mockProcessPayment.mockResolvedValue({ orderId: 'ORD-12345' });
  });

  describe('Happy Path - When Everything Works Elegantly', () => {
    it('completes full checkout flow from shipping to confirmation', async () => {
      const user = userEvent.setup();
      renderCheckout();

      // Shipping step - oh, the addresses! Like little destinations...
      await user.type(screen.getByLabelText(/street address/i), '123 Quirm Lane');
      await user.type(screen.getByLabelText(/city/i), 'Ankh-Morpork');
      await user.selectOptions(screen.getByLabelText(/state/i), 'CA');
      await user.type(screen.getByLabelText(/zip code/i), '12345');
      await user.click(screen.getByRole('button', { name: /continue to payment/i }));

      // Payment step
      await user.type(screen.getByLabelText(/card number/i), '4111111111111111');
      await user.type(screen.getByLabelText(/expiry/i), '12/25');
      await user.type(screen.getByLabelText(/cvv/i), '123');
      await user.type(screen.getByLabelText(/name on card/i), 'Leonard of Quirm');
      await user.click(screen.getByRole('button', { name: /review order/i }));

      // Review and place order
      expect(screen.getByText(/card ending in 1111/i)).toBeInTheDocument();
      await user.click(screen.getByRole('button', { name: /place order/i }));

      await waitFor(() => {
        expect(screen.getByRole('status')).toHaveTextContent(/order confirmed/i);
      });
    });
  });

  describe('Validation - The Error Detection Apparatus', () => {
    it('displays inline errors for empty shipping fields', async () => {
      const user = userEvent.setup();
      renderCheckout();

      await user.click(screen.getByRole('button', { name: /continue to payment/i }));

      expect(screen.getByText(/street address is required/i)).toBeInTheDocument();
      expect(screen.getByLabelText(/street address/i)).toHaveAttribute('aria-invalid', 'true');
    });

    it('validates ZIP code format', async () => {
      const user = userEvent.setup();
      renderCheckout();

      await user.type(screen.getByLabelText(/zip code/i), 'invalid');
      await user.click(screen.getByRole('button', { name: /continue to payment/i }));

      expect(screen.getByText(/valid zip code required/i)).toBeInTheDocument();
    });
  });

  describe('Empty Cart - The Absence of Commerce', () => {
    it('shows empty cart message and prevents checkout', () => {
      renderCheckout([]);

      expect(screen.getByRole('alert')).toHaveTextContent(/cart is empty/i);
      expect(screen.getByRole('button', { name: /continue shopping/i })).toBeInTheDocument();
    });
  });

  describe('Loading States - The Temporal Patience Indicator', () => {
    it('disables buttons and shows processing state during submission', async () => {
      mockProcessPayment.mockImplementation(() => new Promise(() => {})); // Never resolves
      const user = userEvent.setup();
      // ...navigate to review step...

      await user.click(screen.getByRole('button', { name: /place order/i }));

      expect(screen.getByRole('button', { name: /processing/i })).toHaveAttribute('aria-busy', 'true');
    });
  });
});
